package com.kaycee.meritprep

import com.kaycee.meritprep.data.AssessmentQuestion

/**
 * Original Chemistry practice questions mapped to the JAMB topic identifiers.
 * These are authored practice items, not official JAMB or WAEC past questions.
 */
object ChemistryQuestionBank {
    private fun q(id: String, topic: String, prompt: String, options: List<String>, answer: Int, explanation: String) =
        AssessmentQuestion(id, topic, prompt, options, answer, explanation, "MeritPrep original Chemistry practice · $topic", false)

    val all: List<AssessmentQuestion> = listOf(
        q("chem-sep-001","chem-separation","Which method separates an insoluble solid from a liquid?",listOf("Filtration","Fractional distillation","Chromatography","Sublimation"),0,"Filtration retains the insoluble solid on a porous medium while the liquid passes through."),
        q("chem-sep-002","chem-separation","A mixture contains sand and sodium chloride. Which sequence can recover both substances?",listOf("Add water, filter, then crystallise the filtrate","Use a magnet, then distil the sand","Filter the dry mixture, then use chromatography","Sublime both substances"),0,"Salt dissolves in water but sand does not. Filtration separates sand; crystallisation recovers salt from the filtrate."),
        q("chem-sep-003","chem-separation","Which property is mainly used in fractional distillation of miscible liquids?",listOf("Different boiling behaviours","Different magnetic properties","Different particle colours","Different electrical charges"),0,"Fractional distillation separates miscible liquids by differences in volatility and boiling points."),
        q("chem-sep-004","chem-separation","A pure crystalline substance is heated at constant pressure. Which observation is commonly associated with a pure substance during melting?",listOf("A relatively sharp, constant melting temperature","A very broad melting range","Continuous production of a new gas","A permanent change in chemical composition"),0,"A pure substance generally melts over a narrow temperature range at a specified pressure."),
        q("chem-sep-005","chem-separation","Paper chromatography separates dye components because they:",listOf("Move at different rates between stationary and mobile phases","Have different nuclear charges","Are all converted into gases","Are separated by magnetic attraction"),0,"Different affinities for the stationary phase and solvent cause components to travel different distances."),
        q("chem-combination-001","chem-combination","Which statement expresses the law of conservation of mass?",listOf("Total mass remains constant in a closed chemical system","All reactions release heat","A compound always contains equal masses of its elements","Gas volume never changes during reaction"),0,"Atoms are rearranged in ordinary chemical reactions; total mass is conserved in a closed system."),
        q("chem-combination-002","chem-combination","How many moles are present in 9 g of water? (H = 1, O = 16)",listOf("0.25 mol","0.50 mol","1.0 mol","2.0 mol"),1,"Molar mass of water is 18 g mol⁻¹. Amount = 9 ÷ 18 = 0.50 mol."),
        q("chem-combination-003","chem-combination","What is the correct balanced equation for hydrogen reacting with oxygen to form water?",listOf("2H₂ + O₂ → 2H₂O","H₂ + O₂ → H₂O","H₂ + 2O₂ → H₂O","2H₂ + 2O₂ → H₂O"),0,"Two hydrogen molecules react with one oxygen molecule to form two water molecules; atom counts balance on both sides."),
        q("chem-combination-004","chem-combination","The coefficients in a balanced chemical equation represent:",listOf("Relative numbers of particles or moles","Relative atomic masses only","The reaction temperature","The charge on each atom"),0,"Balanced-equation coefficients give stoichiometric ratios of particles and moles."),
        q("chem-combination-005","chem-combination","What is the relative molecular mass of CO₂? (C = 12, O = 16)",listOf("28","32","44","48"),2,"Mr(CO₂) = 12 + (2 × 16) = 44."),
        q("chem-kinetic-gas-001","chem-kinetic-gas","Which statement best describes particles in a gas?",listOf("They move rapidly and randomly, far apart on average","They vibrate only at fixed positions","They are packed in a regular lattice","They cannot be compressed"),0,"Gas particles are widely spaced and move randomly, explaining flow and compressibility."),
        q("chem-kinetic-gas-002","chem-kinetic-gas","A gas occupies 300 cm³ at 100 kPa. At constant temperature its pressure becomes 150 kPa. What is its new volume?",listOf("200 cm³","300 cm³","450 cm³","600 cm³"),0,"Boyle's law: P₁V₁ = P₂V₂. V₂ = (100 × 300) ÷ 150 = 200 cm³."),
        q("chem-kinetic-gas-003","chem-kinetic-gas","Which temperature must be used in gas-law calculations?",listOf("Kelvin","Celsius","Fahrenheit","Any temperature scale"),0,"Gas-law proportionalities require absolute temperature in kelvin."),
        q("chem-kinetic-gas-004","chem-kinetic-gas","At constant pressure, the volume of a fixed amount of gas is directly proportional to its:",listOf("Absolute temperature","Density","Molar mass","Colour"),0,"Charles's law states that volume is directly proportional to kelvin temperature at constant pressure."),
        q("chem-kinetic-gas-005","chem-kinetic-gas","During boiling of a pure liquid at constant pressure, the temperature remains constant because energy is mainly used to:",listOf("Overcome intermolecular attractions","Increase the mass of molecules","Create new atoms","Stop all particle motion"),0,"During the phase change, energy separates particles rather than increasing their average kinetic energy."),
        q("chem-atomic-bonding-001","chem-atomic-bonding","An atom has atomic number 13 and mass number 27. How many neutrons does it contain?",listOf("13","14","27","40"),1,"Neutrons = mass number − atomic number = 27 − 13 = 14."),
        q("chem-atomic-bonding-002","chem-atomic-bonding","Which bond is formed by electrostatic attraction between oppositely charged ions?",listOf("Ionic","Covalent","Metallic","Hydrogen"),0,"Ionic bonding is the electrostatic attraction between positive and negative ions."),
        q("chem-atomic-bonding-003","chem-atomic-bonding","Which particle determines the atomic number of an element?",listOf("Proton","Neutron","Electron","Molecule"),0,"Atomic number is the number of protons in the nucleus."),
        q("chem-atomic-bonding-004","chem-atomic-bonding","Which substance is expected to conduct electricity when molten because its ions are mobile?",listOf("Sodium chloride","Solid sulfur","Pure solid paraffin","Solid iodine"),0,"When molten, sodium chloride contains mobile ions that carry electrical charge."),
        q("chem-atomic-bonding-005","chem-atomic-bonding","Which shape is associated with a methane molecule, CH₄?",listOf("Tetrahedral","Linear","Bent","Trigonal planar"),0,"Four bonding pairs around carbon arrange tetrahedrally to minimise electron-pair repulsion."),
        q("chem-nuclear-001","chem-nuclear","An alpha particle contains:",listOf("Two protons and two neutrons","One proton and one electron","Two electrons and two neutrons","One neutron only"),0,"An alpha particle is the nucleus of a helium-4 atom."),
        q("chem-nuclear-002","chem-nuclear","During beta-minus decay, the atomic number of the daughter nucleus:",listOf("Increases by one","Decreases by one","Decreases by four","Remains unchanged while mass number falls by four"),0,"A neutron changes into a proton and an electron; the proton number rises by one."),
        q("chem-nuclear-003","chem-nuclear","A radioactive sample has a half-life of 4 days. What fraction remains after 12 days?",listOf("One-half","One-quarter","One-eighth","One-sixteenth"),2,"Twelve days is three half-lives. The remaining fraction is (1/2)³ = 1/8."),
        q("chem-nuclear-004","chem-nuclear","Which radiation has no mass and no electric charge?",listOf("Gamma","Alpha","Beta-minus","A proton"),0,"Gamma radiation is electromagnetic radiation and has no rest mass or electric charge."),
        q("chem-nuclear-005","chem-nuclear","Nuclear fission involves:",listOf("Splitting a heavy nucleus into smaller nuclei","Joining two light nuclei","Removing electrons from an atom","Breaking a compound into elements by heating"),0,"Fission splits a heavy nucleus and can release energy and additional neutrons."),
        q("chem-solubility-001","chem-solubility","The substance that dissolves another substance is called the:",listOf("Solvent","Solute","Precipitate","Residue"),0,"The solvent is the dissolving medium; the solute is the substance dissolved."),
        q("chem-solubility-002","chem-solubility","A solution containing less solute than the solubility limit at a given temperature is:",listOf("Unsaturated","Saturated","Supersaturated","A suspension"),0,"An unsaturated solution can dissolve more solute under the same conditions."),
        q("chem-solubility-003","chem-solubility","Which observation is characteristic of a colloid?",listOf("Scattering of a beam of light","Rapid settling of all particles","Complete separation by ordinary filtration","Formation of a pure crystalline solid"),0,"Colloidal particles can scatter light, producing the Tyndall effect."),
        q("chem-solubility-004","chem-solubility","For most gases, solubility in water increases when:",listOf("Pressure increases and temperature decreases","Pressure decreases and temperature increases","Both pressure and temperature increase","The gas is stirred less"),0,"Gas solubility generally rises with pressure and falls as temperature rises."),
        q("chem-solubility-005","chem-solubility","A solution contains 50 g of solute in 100 g water at a temperature where solubility is 30 g per 100 g water. If all 50 g is genuinely dissolved, the solution is:",listOf("Supersaturated","Unsaturated","Saturated with excess solid","A suspension by definition"),0,"A dissolved amount above the equilibrium solubility is supersaturated, though it is metastable."),
        q("chem-pollution-001","chem-pollution","Carbon monoxide is especially dangerous because it:",listOf("Binds strongly to haemoglobin and reduces oxygen transport","Increases oxygen concentration in blood","Has no effect on respiration","Immediately converts nitrogen to oxygen"),0,"Carbon monoxide forms carboxyhaemoglobin and reduces the blood's oxygen-carrying capacity."),
        q("chem-pollution-002","chem-pollution","Eutrophication is commonly caused by excess:",listOf("Nitrates and phosphates entering water","Pure oxygen entering water","Sand entering a river","Sodium chloride evaporating"),0,"Nutrient enrichment can stimulate algal growth; decomposition later depletes dissolved oxygen."),
        q("chem-pollution-003","chem-pollution","A high biochemical oxygen demand in a water sample often indicates:",listOf("A high biodegradable organic load","Absence of microorganisms","Very high dissolved oxygen at all times","No organic matter"),0,"Microorganisms use oxygen to decompose biodegradable material, increasing BOD."),
        q("chem-pollution-004","chem-pollution","Which pair of gases contributes to acid deposition?",listOf("Sulphur dioxide and nitrogen oxides","Oxygen and argon","Hydrogen and helium","Nitrogen and neon"),0,"Sulphur dioxide and nitrogen oxides form acidic compounds in the atmosphere."),
        q("chem-pollution-005","chem-pollution","Which is the best first principle for controlling pollution?",listOf("Prevent or reduce pollutants at their source","Dilute every pollutant in rivers","Move waste to an unlined pit","Burn all plastic waste in open air"),0,"Source prevention reduces the amount of pollution that requires later treatment."),
        q("chem-acids-bases-001","chem-acids-bases","According to the Brønsted–Lowry model, an acid is a:",listOf("Proton donor","Proton acceptor","Neutron donor","Electron-pair acceptor only"),0,"A Brønsted–Lowry acid donates a proton; a base accepts a proton."),
        q("chem-acids-bases-002","chem-acids-bases","Which statement about a strong acid is correct?",listOf("It ionises almost completely in water","It must always be concentrated","It always has a high pH","It cannot be diluted"),0,"Acid strength refers to extent of ionisation, not concentration."),
        q("chem-acids-bases-003","chem-acids-bases","At approximately 25 °C, the pH of a neutral dilute aqueous solution is:",listOf("7","1","4","14"),0,"At 25 °C, neutral water has approximately equal hydronium and hydroxide concentrations and pH 7."),
        q("chem-acids-bases-004","chem-acids-bases","What is the net ionic equation for neutralisation between a strong acid and a strong alkali?",listOf("H⁺ + OH⁻ → H₂O","Na⁺ + Cl⁻ → NaCl","H₂O → H₂ + O₂","H⁺ + Cl⁻ → HCl"),0,"Hydrogen ions react with hydroxide ions to form water."),
        q("chem-acids-bases-005","chem-acids-bases","Which apparatus is used to deliver a measured, variable volume of titrant during an acid–base titration?",listOf("Burette","Beaker","Evaporating dish","Watch glass"),0,"A burette delivers and measures the variable volume of titrant."),
    )

    fun forTopic(topicId: String): List<AssessmentQuestion> = all.filter { it.topicId == topicId }
}
